import { html } from 'lit-html';
import { action } from '@storybook/addon-actions';

export default {
  title: 'Components/Radio Input',
  component: 'bfl-radio-input',
  tags: ['autodocs'],
  argTypes: {
    name: {
      control: 'text',
      description: 'Name of the field (isRequired for bfl-form-wrapper to identify it)',
      defaultValue: 'gender',
    },
    label: {
      control: 'text',
      description: 'Label for the radio input field',
      defaultValue: 'Gender',
    },
    isRequired: {
      control: 'boolean',
      description: 'Indicates if the field is isRequired',
      defaultValue: false,
    },
    inputValues: {
      control: 'array',
      description: 'Array of values for the radio buttons',
      defaultValue: ['Male', 'Female', 'Third Gender'],
    },

    customErrorMessage: {
      control: 'text',
      description: 'Error message to display when the field is invalid',
      defaultValue: 'This field cannot be left blank.',
    },
    hasCustomError: {
      control: 'boolean',
      description: 'Indicates if the input has a custom error',
      defaultValue: false,
    },
  },
};

const Template = ({ name, label, isRequired, inputValues, customErrorMessage,hasCustomError }) => html`
  <bfl-radio-input
    name="${name}"
    label="${label}"
    ?isRequired="${isRequired}"
    .inputValues="${inputValues}"
    customErrorMessage="${customErrorMessage}"
    .hasCustomError="${hasCustomError}"
    @inputChanged="${action('inputChanged')}"
    @onPopUp="${action('onPopUp')}"
  ></bfl-radio-input>
`;

export const Default = Template.bind({});
Default.args = {
  name: 'gender',
  label: 'Gender',
  isRequired: false,
  inputValues: ['Male', 'Female', 'Third Gender'],
  hasCustomError: false,
  customErrorMessage: 'This field cannot be left blank.',
};

export const Required = Template.bind({});
Required.args = {
  name: 'gender',
  label: 'Gender',
  isRequired: true,
  inputValues: ['Male', 'Female', 'Third Gender'],
  customErrorMessage: 'This field cannot be left blank.',
  hasCustomError: false,


};

